#[derive(Clone)]
pub struct NodeFold<R> {
    pub init: Rc<dyn Fn(Rc<Node>) -> R>,
    pub step: Rc<dyn Fn(R, Rc<Edge>, R) -> R>,
    pub _phantom: std::marker::PhantomData<R>,
}

pub fn fold_node<R: Clone>(n: Rc<Node>, algebra: Rc<NodeFold<R>>) -> R {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        n.children.clone().iter().cloned().fold((algebra.init)(n.clone()), |acc: _, e: Rc<Edge>| (algebra.step)(acc, e.clone(), fold_node(e.target.clone(), algebra.clone())))
    })
}

pub fn node_subtree_nodes(root: Rc<Node>) -> Rc<Vec<Rc<Node>>> {
    fold_node(root, Rc::new(NodeFold {
    init: { Rc::new(move |self_| Rc::new(vec![self_.clone()])) },
    step: { Rc::new(move |acc, _edge, sub| v1_rt::concat(acc.clone(), sub.clone())) },
    _phantom: std::marker::PhantomData,
}))
}

pub fn node_subtree_count(n: Rc<Node>) -> i64 {
    fold_node(n, Rc::new(NodeFold {
    init: { Rc::new(move |_| 1) },
    step: { Rc::new(move |acc, _edge, child_count| (acc.clone() + child_count.clone())) },
    _phantom: std::marker::PhantomData,
}))
}

#[derive(Clone)]
pub struct NodeFoldTopDown<A, R> {
    pub init: Rc<dyn Fn(Rc<Node>, A) -> R>,
    pub child_context: Rc<dyn Fn(Rc<Node>, A, Rc<Edge>) -> A>,
    pub step: Rc<dyn Fn(R, Rc<Edge>, R) -> R>,
    pub _phantom: std::marker::PhantomData<(A, R)>,
}

pub fn fold_node_topdown<A: Clone, R: Clone>(n: Rc<Node>, ctx: A, algebra: Rc<NodeFoldTopDown<A, R>>) -> R {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        n.children.clone().iter().cloned().fold((algebra.init)(n.clone(), ctx.clone()), |acc: _, e: Rc<Edge>| (algebra.step)(acc, e.clone(), fold_node_topdown(e.target.clone(), (algebra.child_context)(n.clone(), ctx.clone(), e.clone()), algebra.clone())))
    })
}

#[derive(Clone)]
pub struct NodeFoldDependent<A, R> {
    pub init: Rc<dyn Fn(Rc<Node>, A) -> R>,
    pub first: Rc<dyn Fn(Rc<Node>, Rc<ChildSlot>) -> bool>,
    pub child_context: Rc<dyn Fn(Rc<Node>, A, R, Rc<ChildSlot>) -> A>,
    pub step: Rc<dyn Fn(R, Rc<Edge>, R) -> R>,
    pub _phantom: std::marker::PhantomData<(A, R)>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct ChildSlot {
    pub edge: Rc<Edge>,
    pub ordinal: Rc<ChildOrdinal>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum ChildOrdinal {
    PositionalOrdinal {
        index: i64,
    },
    LabeledChild,
}
impl ChildOrdinal {
    pub fn index(&self) -> i64 {
        match self {
            ChildOrdinal::PositionalOrdinal { index: __val, .. } => __val.clone(),
            ChildOrdinal::LabeledChild => panic!("no index on unit variant"),
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct ChildSlotsAcc {
    pub slots: Rc<Vec<Rc<ChildSlot>>>,
    pub next_positional: i64,
}

pub fn node_child_slots(n: Rc<Node>) -> Rc<Vec<Rc<ChildSlot>>> {
    {
        let walked = n.children.clone().iter().cloned().fold(Rc::new(ChildSlotsAcc {
    slots: Rc::new(vec![]),
    next_positional: 0,
}), |acc: Rc<ChildSlotsAcc>, e: Rc<Edge>| node_child_slots_step(acc, e.clone()));
walked.slots.clone()
}
}

pub fn node_child_slots_step(acc: Rc<ChildSlotsAcc>, e: Rc<Edge>) -> Rc<ChildSlotsAcc> {
    if is_positional(e.clone()) {
        Rc::new(ChildSlotsAcc {
    slots: crate::std_algebra::list_snoc_item(acc.slots.clone(), Rc::new(ChildSlot {
    edge: e.clone(),
    ordinal: Rc::new(ChildOrdinal::PositionalOrdinal {
    index: acc.next_positional.clone(),
}),
})),
    next_positional: v1_rt::int_add(acc.next_positional.clone(), 1),
})
    } else {
        Rc::new(ChildSlotsAcc {
    slots: crate::std_algebra::list_snoc_item(acc.slots.clone(), Rc::new(ChildSlot {
    edge: e.clone(),
    ordinal: Rc::new(ChildOrdinal::LabeledChild),
})),
    next_positional: acc.next_positional.clone(),
})
    }
}

pub fn node_fold_dependent_schedule<A, R>(n: Rc<Node>, algebra: Rc<NodeFoldDependent<A, R>>) -> Rc<Vec<Rc<ChildSlot>>> {
    {
        let slots = node_child_slots(n.clone());
v1_rt::concat(slots.iter().cloned().fold(Rc::new(vec![]), |acc: Rc<Vec<Rc<ChildSlot>>>, s: Rc<ChildSlot>| if (algebra.first)(n.clone(), s.clone()) {
            crate::std_algebra::list_snoc_item(acc, s.clone())
        } else {
            acc
        }), slots.iter().cloned().fold(Rc::new(vec![]), |acc: Rc<Vec<Rc<ChildSlot>>>, s: Rc<ChildSlot>| if (algebra.first)(n.clone(), s.clone()) {
            acc
        } else {
            crate::std_algebra::list_snoc_item(acc, s.clone())
        }))
}
}

pub fn fold_node_dependent<A: Clone, R: Clone>(n: Rc<Node>, ctx: A, algebra: Rc<NodeFoldDependent<A, R>>) -> R {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        node_fold_dependent_schedule(n.clone(), algebra.clone()).iter().cloned().fold((algebra.init)(n.clone(), ctx.clone()), |acc: _, s: Rc<ChildSlot>| (algebra.step)(acc.clone(), s.edge.clone(), fold_node_dependent(s.edge.target.clone(), (algebra.child_context)(n.clone(), ctx.clone(), acc.clone(), s.clone()), algebra.clone())))
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum BindSlot {
    BindBinderSlot,
    BindValueSlot,
    BindBodySlot,
}

pub fn bind_positional_slot(ordinal: i64) -> BindSlot {
    if (ordinal.clone() == 0) {
        BindSlot::BindBinderSlot
    } else {
        if (ordinal.clone() == 1) {
            BindSlot::BindValueSlot
        } else {
            BindSlot::BindBodySlot
        }
    }
}

pub fn positional_arity_admitted(n: Rc<Node>) -> bool {
    positional_arity_admitted_in(n.children.clone())
}

pub fn positional_arity_admitted_in(children: Rc<Vec<Rc<Edge>>>) -> bool {
    {
        let arity = positional_child_count(children);
((arity.clone() == 2) || (arity.clone() == 3))
}
}

pub fn bind_positional_slot_in_arity(ordinal: i64, arity: i64) -> Option<BindSlot> {
    if (arity.clone() == 2) {
        if (ordinal.clone() == 0) {
            crate::std_optional::optional_present(BindSlot::BindValueSlot)
        } else {
            if (ordinal.clone() == 1) {
                crate::std_optional::optional_present(BindSlot::BindBodySlot)
            } else {
                crate::std_optional::optional_absent()
            }
        }
    } else {
        if (arity.clone() == 3) {
            crate::std_optional::optional_present(bind_positional_slot(ordinal.clone()))
        } else {
            crate::std_optional::optional_absent()
        }
    }
}

pub fn bind_slot_target(n: Rc<Node>, slot: BindSlot) -> Option<Rc<Node>> {
    if positional_arity_admitted(n.clone()) {
        bind_slot_target_in_arity(n.clone(), slot)
    } else {
        crate::std_optional::optional_absent()
    }
}

pub fn bind_slot_target_in_arity(n: Rc<Node>, slot: BindSlot) -> Option<Rc<Node>> {
    {
        let arity = (positional_child_target_nodes(n.clone()).len() as i64);
positional_target_where(n.children.clone(), 0, |i| (bind_positional_slot_in_arity(i, arity.clone()) == crate::std_optional::optional_present(slot.clone())))
}
}

pub fn match_slot_target(n: Rc<Node>, slot: MatchSlot) -> Option<Rc<Node>> {
    positional_target_where(n.children.clone(), 0, |i| (match_positional_slot(i) == slot.clone()))
}

pub fn match_role_slots(n: Rc<Node>, role: MatchSlot) -> Rc<Vec<Rc<ChildSlot>>> {
    node_child_slots(n).iter().cloned().fold(Rc::new(vec![]), |acc: Rc<Vec<Rc<ChildSlot>>>, s: Rc<ChildSlot>| match_role_slots_step(acc, s.clone(), role.clone()))
}

pub fn match_role_slots_step(acc: Rc<Vec<Rc<ChildSlot>>>, s: Rc<ChildSlot>, role: MatchSlot) -> Rc<Vec<Rc<ChildSlot>>> {
    match (*s.ordinal.clone()).clone() {
    ChildOrdinal::PositionalOrdinal { index: i, .. } => if (match_positional_slot(i.clone()) == role.clone()) {
        crate::std_algebra::list_snoc_item(acc, s.clone())
    } else {
        acc.clone()
    },
    ChildOrdinal::LabeledChild => acc.clone(),
}
}

pub fn branch_slot_target(n: Rc<Node>, slot: BranchSlot) -> Option<Rc<Node>> {
    if positional_arity_admitted(n.clone()) {
        branch_slot_target_in_arity(n.clone(), slot)
    } else {
        crate::std_optional::optional_absent()
    }
}

pub fn branch_positional_shape_admitted(n: Rc<Node>) -> bool {
    (all_edges_positional(n.children.clone()) && positional_arity_admitted(n.clone()))
}

pub fn branch_slot_target_in_arity(n: Rc<Node>, slot: BranchSlot) -> Option<Rc<Node>> {
    positional_target_where(n.children.clone(), 0, |i| (branch_positional_slot(i) == crate::std_optional::optional_present(slot.clone())))
}

pub fn positional_target_where(edges: Rc<Vec<Rc<Edge>>>, ordinal: i64, wanted: impl Fn(i64) -> bool + Clone) -> Option<Rc<Node>> {
    { let __fm = edges.clone(); if __fm.is_empty() { crate::std_optional::optional_absent() } else { let e = (*__fm)[0].clone(); let rest: Rc<Vec<_>> = Rc::new(__fm.skip(1)); positional_target_where_at(e.clone(), rest.clone(), ordinal, wanted) } }
}

pub fn positional_target_where_at(e: Rc<Edge>, rest: Rc<Vec<Rc<Edge>>>, ordinal: i64, wanted: impl Fn(i64) -> bool + Clone) -> Option<Rc<Node>> {
    if is_positional(e.clone()) {
        if wanted(ordinal.clone()) {
            crate::std_optional::optional_present(e.target.clone())
        } else {
            positional_target_where(rest.clone(), v1_rt::int_add(ordinal.clone(), 1), wanted.clone())
        }
    } else {
        positional_target_where(rest.clone(), ordinal.clone(), wanted.clone())
    }
}

