pub fn loop_behavior_edges_conform(children: Rc<Vec<Rc<Edge>>>) -> bool {
    {
        let bound_edges = core_occurrences(Rc::new(CoreEdgeLabel::LoopBoundEdge), children.clone());
let carrier_edges = core_occurrences(Rc::new(CoreEdgeLabel::LoopCarrierEdge), children.clone());
let domain_edges = core_occurrences(Rc::new(CoreEdgeLabel::LoopDomainEdge), children.clone());
let realized_edges = core_occurrences(Rc::new(CoreEdgeLabel::LoopRealizedDeclarationEdge), children.clone());
((((((bound_edges.clone() == 1) && (carrier_edges.clone() <= 1)) && (domain_edges.clone() <= 1)) && (realized_edges.clone() <= 1)) && loop_body_edges_conform(children.clone())) && (loop_positional_child_count(children.clone()) >= 1))
}
}

