#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct SortedSymbolWalk {
    pub rest: Rc<Vec<Symbol>>,
    pub previous: Rc<Vec<Symbol>>,
    pub ok: bool,
}

pub fn symbols_are_one_distinct_set(a: Rc<Vec<Symbol>>, b: Rc<Vec<Symbol>>) -> bool {
    if ((a.clone().len() as i64) != (b.clone().len() as i64)) {
        false
    } else {
        {
            let walk = crate::std_algebra::list_sort_by_key(a.clone(), |x| x.clone(), symbol_total_order()).iter().cloned().fold(Rc::new(SortedSymbolWalk {
    rest: crate::std_algebra::list_sort_by_key(b.clone(), |x| x.clone(), symbol_total_order()),
    previous: Rc::new(vec![]),
    ok: true,
}), |acc: Rc<SortedSymbolWalk>, x: Symbol| { let __fm = acc.rest.clone(); if __fm.is_empty() { Rc::new(SortedSymbolWalk {
    rest: Rc::new(vec![]),
    previous: Rc::new(vec![x.clone()]),
    ok: false,
}) } else { let y = (*__fm)[0].clone(); let more: Rc<Vec<_>> = Rc::new(__fm.skip(1)); Rc::new(SortedSymbolWalk {
    rest: more.clone(),
    previous: Rc::new(vec![x.clone()]),
    ok: ((acc.ok.clone() && (x.clone() == y.clone())) && !(acc.previous.clone() == Rc::new(vec![x.clone()]))),
}) } });
walk.ok.clone()
}
    }
}

