pub fn fold_node_content_hash<R: Clone>(n: Rc<Node>, algebra: Rc<NodeFold<R>>) -> R {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        {
            let canonical = canonicalize_node_for_content_hash(n);
canonical.children.clone().iter().cloned().fold((algebra.init)(canonical.clone()), |acc: _, e: Rc<Edge>| (algebra.step)(acc, e.clone(), fold_node_content_hash(e.target.clone(), algebra.clone())))
}
    })
}

