pub fn byte_limb_hash_peano_digest(limb: i64) -> Rc<Fnv1a64Structural> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        if ((limb.clone() < 0) || (limb.clone() > 255)) {
            crate::std_content_hash::content_hash_atom("canonical_tag_byte_limb_out_of_range".to_string())
        } else {
            if (limb.clone() == 0) {
                crate::std_content_hash::content_hash_atom("canonical_tag_scalar_int_zero".to_string())
            } else {
                if (limb.clone() == 1) {
                    crate::std_content_hash::content_hash_atom("canonical_tag_scalar_int_one".to_string())
                } else {
                    combine_hash(crate::std_content_hash::content_hash_atom("canonical_tag_scalar_int_succ".to_string()), byte_limb_hash_peano_digest(v1_rt::int_sub(limb.clone(), 1)))
                }
            }
        }
    })
}

