pub fn byte_offset_quotient_divide_by_256_steps(mut __tco_loop_quotient: i64, mut __tco_loop_steps: i64) -> i64 {
    { loop {
        #[allow(unused_mut)]
        let mut quotient = __tco_loop_quotient;
        #[allow(unused_mut)]
        let mut steps = __tco_loop_steps;
        if (steps.clone() <= 0) {
            break quotient.clone();
} else {
            {
                let __tco_0 = v1_rt::int_div(quotient, 256);
let __tco_1 = v1_rt::int_sub(steps, 1);
__tco_loop_quotient = __tco_0;
__tco_loop_steps = __tco_1;
continue;
}
}
} }
}

pub fn byte_offset_residual_quotient_magnitude_window_digest(quotient: i64, shift_steps: i64) -> Rc<Fnv1a64Structural> {
    {
        let shifted = byte_offset_quotient_divide_by_256_steps(quotient, shift_steps.clone());
if ((shift_steps.clone() == byte_offset_residual_quotient_magnitude_max_shift()) && (shifted.clone() >= v1_rt::int_mul(256, 256))) {
            combine_hash(byte_offset_residual_quotient_limb_pair_digest(shifted.clone()), byte_offset_overflow_quotient_high_band_terminal_digest(v1_rt::int_div(shifted.clone(), 65536), byte_offset_cache_digest_overflow_limbs()))
        } else {
            byte_offset_residual_quotient_limb_pair_digest(shifted.clone())
        }
}
}

