        combine_hash(crate::std_content_hash::content_hash_atom("canonical_tag_byte_offset_residual_quotient_limb_pair".to_string()), combine_hash(byte_offset_byte_digest(v1_rt::int_sub(quotient.clone(), v1_rt::int_mul(v1_rt::int_div(quotient.clone(), 256), 256))), byte_offset_byte_digest(v1_rt::int_div(quotient.clone(), 256))))
