pub fn byte_offset_byte_limb_projection_node(limb: i64) -> Rc<Node> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        if ((limb.clone() < 0) || (limb.clone() > 255)) {
            node_offset_atom("canonical_tag_byte_limb_out_of_range".to_string())
        } else {
            if (limb.clone() == 0) {
                node_offset_atom("canonical_tag_scalar_int_zero".to_string())
            } else {
                if (limb.clone() == 1) {
                    node_offset_atom("canonical_tag_scalar_int_one".to_string())
                } else {
                    node_offset_conj(Rc::new(vec![node_offset_named_edge("byte_offset_proj_succ_edge".to_string(), node_offset_atom("canonical_tag_scalar_int_succ".to_string())), node_offset_named_edge("byte_offset_proj_pred_edge".to_string(), byte_offset_byte_limb_projection_node(v1_rt::int_sub(limb.clone(), 1)))]))
                }
            }
        }
    })
}

